// =============================================================================
// SECRET IN SERVICE ENV
// =============================================================================

export const secretInServiceEnv = test({
  name: "secret used in service environment",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-env",
  },

  config: `
    import { service, config } from "vyft";

    export const app = service("app", {
      image: "nginx:alpine",
      env: {
        DB_PASSWORD: config("db-password", { secret: true }),
        API_KEY: config("api-key", { secret: true }),
      },
    });
  `,

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);
    await vyft.stage.create(id);

    await vyft.deploy();

    const dbPassword = await vyft.config.get("db-password");
    const apiKey = await vyft.config.get("api-key");

    assert(dbPassword, "should have db-password");
    assert(apiKey, "should have api-key");
    assert.notStrictEqual(dbPassword, apiKey, "secrets should be unique");
  },
});

