// =============================================================================
// SECRET WITH MANUAL VALUE
// =============================================================================

export const secretManualValue = test({
  name: "manually set secret value",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-manual",
  },

  config: `
    import { service, config } from "vyft";

    export const app = service("app", {
      image: "nginx:alpine",
      env: {
        SECRET: config("manual-secret", { secret: true }),
      },
    });
  `,

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);
    await vyft.stage.create(id);

    // Set manual value before deploy
    await vyft.config.set("manual-secret", "my-manual-value", { secret: true });

    await vyft.deploy();

    const value = await vyft.config.get("manual-secret");
    assert.strictEqual(value, "my-manual-value", "should use manual value");
  },
});

export const secretManualOverridesGenerated = test({
  name: "manual secret overrides auto-generated",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-override",
  },

  config: `
    import { service, config } from "vyft";

    export const app = service("app", {
      image: "nginx:alpine",
      env: {
        SECRET: config("override-secret", { secret: true }),
      },
    });
  `,

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);
    await vyft.stage.create(id);

    // Deploy to generate
    await vyft.deploy();
    const generated = await vyft.config.get("override-secret");

    // Override with manual value
    await vyft.config.set("override-secret", "manual-override", { secret: true });
    await vyft.deploy();

    const override = await vyft.config.get("override-secret");
    assert.strictEqual(override, "manual-override");
    assert.notStrictEqual(override, generated);
  },
});

// =============================================================================
// SECRET NON-GENERATED
// =============================================================================

export const secretNonGenerated = test({
  name: "secret with generated=false requires manual value",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-nogen",
  },

  config: `
    import { service, config } from "vyft";

    export const app = service("app", {
      image: "nginx:alpine",
      env: {
        SECRET: config("required-secret", { secret: true, generated: false }),
      },
    });
  `,

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);
    await vyft.stage.create(id);

    // Deploy without setting should fail
    try {
      await vyft.deploy();
      assert.fail("should fail without required secret");
    } catch {
      // Expected
    }

    // Set and deploy should succeed
    await vyft.config.set("required-secret", "provided-value", { secret: true });
    await vyft.deploy();

    const value = await vyft.config.get("required-secret");
    assert.strictEqual(value, "provided-value");
  },
});

// =============================================================================
// SECRET ISOLATION
// =============================================================================

export const secretIsolatedByStage = test({
  name: "secrets are isolated by stage",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-isolation",
  },

  config: `
    import { config } from "vyft";

    export const apiKey = config("api-key", { secret: true });
  `,

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);

    // Generate in staging
    await vyft.stage.create("staging");
    await vyft.deploy();
    const stagingKey = await vyft.config.get("api-key");

    // Generate in production
    await vyft.stage.create("production");
    await vyft.deploy();
    const prodKey = await vyft.config.get("api-key");

    // Should be different
    assert.notStrictEqual(stagingKey, prodKey, "secrets should differ by stage");

    // Clean up
    await vyft.stage.use("staging");
    await vyft.destroy();
    await vyft.stage.use("production");
    await vyft.destroy();
  },
});

// =============================================================================
// MULTIPLE SECRETS
// =============================================================================

export const multipleSecretsGenerated = test({
  name: "multiple secrets generated independently",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-multi",
  },

  config: `
    import { service, config } from "vyft";

    export const app = service("app", {
      image: "nginx:alpine",
      env: {
        SECRET1: config("secret-1", { secret: true }),
        SECRET2: config("secret-2", { secret: true }),
        SECRET3: config("secret-3", { secret: true }),
      },
    });
  `,

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);
    await vyft.stage.create(id);

    await vyft.deploy();

    const s1 = await vyft.config.get("secret-1");
    const s2 = await vyft.config.get("secret-2");
    const s3 = await vyft.config.get("secret-3");

    assert(s1, "should have secret-1");
    assert(s2, "should have secret-2");
    assert(s3, "should have secret-3");

    // All should be unique
    assert.notStrictEqual(s1, s2);
    assert.notStrictEqual(s2, s3);
    assert.notStrictEqual(s1, s3);
  },
});

