// =============================================================================
// SECRET CONFIG LS
// =============================================================================

export const secretConfigLsShowsFlag = test({
  name: "config ls shows secret flag",

  env: {
    VYFT_PASSPHRASE: "test-passphrase-ls",
  },

  run: async ({ id, vyft }) => {
    await vyft.context.create(id);
    await vyft.stage.create(id);

    await vyft.config.set("plain-value", "not-secret");
    await vyft.config.set("secret-value", "is-secret", { secret: true });

    const result = await vyft.config.ls();

    const plain = result.items.find((i) => i.name === "plain-value");
    const secret = result.items.find((i) => i.name === "secret-value");

    assert(plain, "should have plain value");
    assert(secret, "should have secret value");
    assert.strictEqual(plain.secret, false);
    assert.strictEqual(secret.secret, true);
  },
});
